-- 限时秒杀 is the third mode beside 预售 and 拼团 in the product editor, so a role that may
-- run presales (`presale:activity:write`, the 营销 job) may run flash sales too. Data only.
-- Matches nothing on a fresh database, and a second run inserts nothing.
INSERT INTO "role_permissions" ("role_id", "permission")
SELECT "role_permissions"."role_id", "atom"
FROM "role_permissions"
CROSS JOIN unnest(ARRAY['flashsale:activity:read', 'flashsale:activity:write']) AS "atom"
WHERE "role_permissions"."permission" = 'presale:activity:write'
ON CONFLICT DO NOTHING;
--> statement-breakpoint
-- What the new writer reads (core/src/system/permission-requirements.ts), as 0013 did.
INSERT INTO "role_permissions" ("role_id", "permission")
SELECT "role_permissions"."role_id", "requirement"."needs"
FROM "role_permissions"
JOIN (VALUES
  ('flashsale:activity:write', 'flashsale:activity:read'),
  ('flashsale:activity:write', 'catalog:product:read')
) AS "requirement" ("atom", "needs") ON "requirement"."atom" = "role_permissions"."permission"
ON CONFLICT DO NOTHING;
